script:
try:
    crop = frappe.form_dict.get("crop")
    pests = frappe.get_all("Pest", fields=["name", "common_name"])
    pest_names = [p.name for p in pests]

    filter_row_filters = {"pest": ["in", pest_names]} if pest_names else {"pest": ""}
    if crop:
        filter_row_filters["parent"] = crop
        filter_row_filters["parenttype"] = "Crop Scouted"
    filter_rows = frappe.get_all(
        "Pest Filter",
        filters=filter_row_filters,
        fields=["name", "pest"],
        limit_page_length=0,
    )
    row_to_pest = {r.name: r.pest for r in filter_rows}

    stages_by_pest = {}
    if row_to_pest:
        seen = set()
        for s in frappe.get_all(
            "Pests Stages",
            filters={"parent": ["in", list(row_to_pest.keys())], "parenttype": "Pest Filter"},
            fields=["parent", "stage", "image"],
            limit_page_length=0,
        ):
            pest_name = row_to_pest.get(s.parent)
            if not pest_name or not s.stage:
                continue
            key = (pest_name, s.stage)
            if key in seen:
                continue
            seen.add(key)
            stages_by_pest.setdefault(pest_name, []).append({"stage": s.stage, "image": s.image})

    pest_data = [
        {"common_name": pest.common_name, "stages": stages_by_pest.get(pest.name, [])}
        for pest in pests
    ]
    frappe.response["data"] = {"pests": pest_data}

except Exception as e:
    frappe.log_error(message=e, title="Get pests data error")

def assign_variety_from_sectors(sectors, bed_number):
    try:
        bed_int = int(bed_number)
    except Exception:
        return None
    for sector in sectors:
        try:
            if int(sector.from_bed) <= bed_int <= int(sector.to_bed):
                return sector.sector
        except Exception:
            continue
    return None

def safe_parse_json(json_string):
    """Parses a JSON string and handles potential errors gracefully."""
    if not json_string:
        return {}
    try:
        return json.loads(json_string)
    except json.JSONDecodeError as e:
        frappe.throw(f"Invalid JSON format: {e}")
    except Exception as e:
        frappe.throw(f"Error parsing JSON: {e}")

doc_name = frappe.form_dict.get("doc_name")
try:
    if not doc_name:
        frappe.throw(
            "Error: Document name is missing. Please save the document and try again.")

    doc = frappe.get_doc("Bed And Zone Automation", doc_name)
    beds_created_count = 0
    zones_created_count = 0
    skipped_beds_count = 0
    skipped_zones_count = 0

    greenhouse = doc.name
    zones_geojson = doc.zones_geojson or ""
    sectors = doc.sectors or []

    for line in zones_geojson.strip().splitlines():
        if not line.strip():
            continue

        feature_collection = safe_parse_json(line)
        if not feature_collection:
            continue

        for feature in feature_collection.get("features", []):
            props = feature.get("properties", {})
            bed_number = str(props.get("line_id"))
            zone_number = str(props.get("zone_id"))

            if not bed_number or not zone_number:
                continue

            variety = assign_variety_from_sectors(sectors, bed_number)

            # --- Bed ---
            existing_bed_name = frappe.db.exists({
                "doctype": "Bed",
                "greenhouse": greenhouse,
                "bed": bed_number
            })

            bed_doc = None
            if existing_bed_name:
                skipped_beds_count = skipped_beds_count + 1
                bed_doc = frappe.get_doc("Bed", existing_bed_name)
            else:
                try:
                    bed_doc = frappe.get_doc({
                        "doctype": "Bed",
                        "greenhouse": greenhouse,
                        "bed": bed_number,
                        "variety": variety or ""  # Ensure variety is an empty string if None
                    })
                    bed_doc.insert(ignore_permissions=True)
                    beds_created_count = beds_created_count + 1
                except Exception as e:
                    frappe.log_error(f"Failed to create Bed: {e}", "Bed And Zone Automation Error")
                    continue  # Skip to the next feature if bed creation fails

            if not bed_doc:
                continue

            # --- Zone ---
            existing_zone_name = frappe.db.exists({
                "doctype": "Zone",
                "greenhouse": greenhouse,
                "bed": bed_doc.name,
                "zone": zone_number
            })

            if existing_zone_name:
                skipped_zones_count = skipped_zones_count + 1
            else:
                try:
                    zone_doc = frappe.get_doc({
                        "doctype": "Zone",
                        "greenhouse": greenhouse,
                        "bed": bed_doc.name,
                        "zone": zone_number,
                        "raw_geojson": line
                    })
                    zone_doc.insert(ignore_permissions=True)
                    zones_created_count = zones_created_count + 1
                except Exception as e:
                    frappe.log_error(f"Failed to create Zone: {e}", "Bed And Zone Automation Error")

    frappe.msgprint(
        f"{beds_created_count} beds created, {skipped_beds_count} skipped. "
        f"{zones_created_count} zones created, {skipped_zones_count} skipped."
    )

except Exception as e:
    frappe.throw(f"Error in Bed & Zone Automation: {e}")

try:
    plant_diseases = frappe.get_all(
        "Plant Disease",
        fields=["name", "common_name"]
    )
    plant_disease_data = []
    for plant_disease in plant_diseases:
        stages = frappe.get_all(
            "Disease Stages",
            filters={"parent": plant_disease.name},
            fields=["stage", "image"]
        )
        plant_disease_data.append({
            "common_name": plant_disease.common_name,
            "stages": stages
        })
    frappe.response["data"] = {
        "plant_diseases": plant_disease_data
    }

except Exception as e:
    frappe.log_error(message=e, title="Get plant diseases data error")

try:
    data = frappe.form_dict.get("data")
    item_names = []
    if data:
        item_names = json.loads(data).get("chemicals", [])

    code_item_map = {}
    item_uom_map = {}
    code_group_map = {}

    if item_names:
        items = frappe.get_list(
            "Item",
            filters={"item_name": ("in", item_names)},
            fields=["item_name", "item_code", "stock_uom", "item_group"],
            as_list=False
        )
        for item in items:
            name = item.get("item_name")
            code = item.get("item_code")
            code_item_map[code] = name
            item_uom_map[name] = item.get("stock_uom")
            code_group_map[code] = item.get("item_group") or ""

    chemical_codes = [c for c, g in code_group_map.items() if g != "Fertilizer"]
    fertilizer_codes = [c for c, g in code_group_map.items() if g == "Fertilizer"]

    allowed_farms = frappe.get_all(
        "Spray Plan Allowed Farm",
        filters={"parenttype": "Spray Plan Settings"},
        pluck="farm",
    )
    allowed_farms = [f for f in allowed_farms if f]

    def _whs(prefix):
        if not allowed_farms:
            return []
        return frappe.get_list(
            "Warehouse",
            filters={
                "name": ("like", prefix + " %"),
                "custom_farm": ("in", allowed_farms),
                "disabled": 0,
            },
            pluck="name",
            order_by="name asc",
        )

    chemical_warehouses = _whs("Chemical Store")
    fertilizer_warehouses = _whs("Fertilizer Store")

    def _balances(codes, warehouses):
        out = {c: {wh: 0.0 for wh in warehouses} for c in codes}
        if not codes or not warehouses:
            return out
        bins = frappe.get_list(
            "Bin",
            filters={
                "item_code": ("in", codes),
                "warehouse": ("in", warehouses),
            },
            fields=["item_code", "warehouse", "actual_qty"],
            as_list=False,
        )
        for b in bins:
            c = b.get("item_code")
            wh = b.get("warehouse")
            if c in out and wh in out[c]:
                out[c][wh] = b.get("actual_qty") or 0.0
        return out

    chem_by_code = _balances(chemical_codes, chemical_warehouses)
    fert_by_code = _balances(fertilizer_codes, fertilizer_warehouses)

    def _by_name(balances_by_code):
        return {code_item_map[c]: bals for c, bals in balances_by_code.items() if code_item_map.get(c)}

    chemical_balances = _by_name(chem_by_code)
    fertilizer_balances = _by_name(fert_by_code)
    combined_balances = {}
    combined_balances.update(chemical_balances)
    combined_balances.update(fertilizer_balances)

    frappe.response["data"] = {
        "stock_balances": combined_balances,
        "item_uom_map": item_uom_map,
        "chemical_balances": chemical_balances,
        "chemical_warehouses": chemical_warehouses,
        "fertilizer_balances": fertilizer_balances,
        "fertilizer_warehouses": fertilizer_warehouses,
    }

except Exception as e:
    frappe.log_error(title="Server Script Error", message=str(e))
    frappe.throw("Error fetching stock balances: " + str(e))

try:
    greenhouse_name = frappe.form_dict.get("greenhouse_name")

    if not greenhouse_name:
        frappe.response['message'] = "Greenhouse name parameter 'greenhouse_name' is missing."
    else:
        beds_list = frappe.db.get_list(
            "Bed",
            filters={"greenhouse": greenhouse_name},
            fields=["bed", "name"]
        )

        frappe.response['data'] = beds_list

except Exception as e:
    frappe.response['message'] = "An unexpected server error occurred: " + str(e)
